CREATE TABLE customer_auth (customer_id UUID PRIMARY KEY REFERENCES customers(id) ON DELETE RESTRICT, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE staff_roles (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE permissions (id TEXT PRIMARY KEY, description TEXT NOT NULL);
CREATE TABLE staff_role_permissions (role_id TEXT NOT NULL REFERENCES staff_roles(id) ON DELETE RESTRICT, permission_id TEXT NOT NULL REFERENCES permissions(id) ON DELETE RESTRICT, PRIMARY KEY(role_id,permission_id));
CREATE TABLE staff_users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), full_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role_id TEXT NOT NULL REFERENCES staff_roles(id) ON DELETE RESTRICT, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO staff_roles(id,name) VALUES ('admin','Administrator'),('operations','Operations') ON CONFLICT DO NOTHING;
INSERT INTO permissions(id,description) VALUES ('bookings.read','Read booking requests'),('bookings.cancel','Cancel eligible requests'),('contacts.read','Read contact inbox'),('services.read','Read service catalogue'),('services.manage','Manage service catalogue'),('customers.read','Read customer accounts'),('staff.manage','Manage staff accounts') ON CONFLICT DO NOTHING;
INSERT INTO staff_role_permissions(role_id,permission_id) VALUES ('admin','bookings.read'),('admin','bookings.cancel'),('admin','contacts.read'),('admin','services.read'),('admin','services.manage'),('admin','customers.read'),('admin','staff.manage'),('operations','bookings.read'),('operations','bookings.cancel'),('operations','contacts.read'),('operations','services.read'),('operations','customers.read') ON CONFLICT DO NOTHING;
